{"point":{"id":"generation","title":"Validated Diagram Generation","rationale":"DiagramEditService and DiagramBatchService coordinate asynchronous creation, extension, scoped replacement, and alternatives against pinned input revisions. Model execution remains behind generator ports; validated submission and domain revision issuance precede application. Runs distinguish generation from application acknowledgement so ambiguous retries do not regenerate or duplicate edits.","sourcePaths":["application/core/diagrams/generateDiagram.ts","application/mapping/agent/diagramEditService.ts","application/mapping/agent/diagramBatchService.ts","application/core/agents/agentWorkflow.ts","infrastructure/core/agents/agentRuntime.ts","infrastructure/core/agents/validatedSubmission.ts","infrastructure/mapping/agents/diagram-edit/diagramEditRuntime.ts"],"relationships":[{"pointId":"diagrams","label":"Validates generated edits and issues revisions","kind":"call"},{"pointId":"contexts","label":"Seeds generation with captured context","kind":"dependency"},{"pointId":"canvas","label":"Applies prepared revisions through versioned canvas ports","kind":"call"}]},"sources":[{"path":"application/core/diagrams/generateDiagram.ts","text":"import type { DiagramGenerationRequest, DiagramGenerator, GenerationOptions } from '../../../domain/core/diagrams/diagramGeneration';
import { getDiagramRevision, submitStoredDiagramEdit } from '../../../domain/core/diagrams/diagramRevisionStore';

/** Runs an agent; domain validation and revision publication happen only after success. */
export async function generateDiagram(generator: DiagramGenerator, request: DiagramGenerationRequest, options: GenerationOptions = {}) {
  options.signal?.throwIfAborted();
  const base = request.baseRevisionId ? getDiagramRevision(request.baseRevisionId) : undefined;
  if (base && base.diagram.id !== request.input.id) throw Error('Generation base belongs to another diagram');
  const raw = await generator.generate(structuredClone({ ...request, nodeRefs: base?.nodeRefs ?? {} }), options);
  options.signal?.throwIfAborted();
  return submitStoredDiagramEdit(request, { ascii: raw.ascii, structureKind: raw.structureKind ?? request.input.structureKind ?? 'diagram',
    mappings: raw.mappings ? [...raw.mappings] : undefined, replacementRanges: raw.replacementRanges }, raw.nodeCorrespondence);
}
